   114→// --- HELPER FUNCTIONS ---
   115→export function extractRecordId(url: string | null | undefined): string | null {
   116→  if (!url) return null;
   117→  // Extrahiere die letzten 24 Hex-Zeichen mit Regex
   118→  const match = url.match(/([a-f0-9]{24})$/i);
   119→  return match ? match[1] : null;
   120→}
   121→
   122→export function createRecordUrl(appId: string, recordId: string): string {
   123→  return `https://my.living-apps.de/rest/apps/${appId}/records/${recordId}`;
   124→}
   125→
   126→async function callApi(method: string, endpoint: string, data?: any) {
   127→  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
   128→    method,
   129→    headers: { 'Content-Type': 'application/json' },
   130→    credentials: 'include',  // Nutze Session Cookies für Auth
   131→    body: data ? JSON.stringify(data) : undefined
   132→  });
   133→  if (!response.ok) throw new Error(await response.text());
   134→  // DELETE returns often empty body or simple status
   135→  if (method === 'DELETE') return true;
   136→  return response.json();
   137→}
   138→
   139→/** Upload a file to LivingApps. Returns the file URL for use in record fields. */
   140→export async function uploadFile(file: File | Blob, filename?: string): Promise<string> {
   141→  const formData = new FormData();
   142→  formData.append('file', file, filename ?? (file instanceof File ? file.name : 'upload'));
   143→  const res = await fetch(`${API_BASE_URL}/files`, {
   144→    method: 'POST',
   145→    credentials: 'include',
   146→    body: formData,
   147→  });
   148→  if (!res.ok) throw new Error(`File upload failed: ${res.status}`);
   149→  const data = await res.json();
   150→  return data.url;
   151→}
