   367→## src/hooks/useDashboardData.ts
   368→```
   369→import { useState, useEffect, useMemo, useCallback } from 'react';
   370→import type { Schichtvorlagen, Schichtzuweisungen, Mitarbeiter, Verfuegbarkeit } from '@/types/app';
   371→import { LivingAppsService } from '@/services/livingAppsService';
   372→
   373→export function useDashboardData() {
   374→  const [schichtvorlagen, setSchichtvorlagen] = useState<Schichtvorlagen[]>([]);
   375→  const [schichtzuweisungen, setSchichtzuweisungen] = useState<Schichtzuweisungen[]>([]);
   376→  const [mitarbeiter, setMitarbeiter] = useState<Mitarbeiter[]>([]);
   377→  const [verfuegbarkeit, setVerfuegbarkeit] = useState<Verfuegbarkeit[]>([]);
   378→  const [loading, setLoading] = useState(true);
   379→  const [error, setError] = useState<Error | null>(null);
   380→
   381→  const fetchAll = useCallback(async () => {
   382→    setError(null);
   383→    try {
   384→      const [schichtvorlagenData, schichtzuweisungenData, mitarbeiterData, verfuegbarkeitData] = await Promise.all([
   385→        LivingAppsService.getSchichtvorlagen(),
   386→        LivingAppsService.getSchichtzuweisungen(),
   387→        LivingAppsService.getMitarbeiter(),
   388→        LivingAppsService.getVerfuegbarkeit(),
   389→      ]);
   390→      setSchichtvorlagen(schichtvorlagenData);
   391→      setSchichtzuweisungen(schichtzuweisungenData);
   392→      setMitarbeiter(mitarbeiterData);
   393→      setVerfuegbarkeit(verfuegbarkeitData);
   394→    } catch (err) {
   395→      setError(err instanceof Error ? err : new Error('Fehler beim Laden der Daten'));
   396→    } finally {
   397→      setLoading(false);
   398→    }
   399→  }, []);
   400→
   401→  useEffect(() => { fetchAll(); }, [fetchAll]);
   402→
   403→  const schichtvorlagenMap = useMemo(() => {
   404→    const m = new Map<string, Schichtvorlagen>();
   405→    schichtvorlagen.forEach(r => m.set(r.record_id, r));
   406→    return m;
   407→  }, [schichtvorlagen]);
   408→
   409→  const mitarbeiterMap = useMemo(() => {
   410→    const m = new Map<string, Mitarbeiter>();
   411→    mitarbeiter.forEach(r => m.set(r.record_id, r));
   412→    return m;
   413→  }, [mitarbeiter]);
   414→
   415→  return { schichtvorlagen, setSchichtvorlagen, schichtzuweisungen, setSchichtzuweisungen, mitarbeiter, setMitarbeiter, verfuegbarkeit, setVerfuegbarkeit, loading, error, fetchAll, schichtvorlagenMap, mitarbeiterMap };
   416→}
   417→```
