   543→
   544→export async function chatCompletion(
   545→  messages: ChatMessage[],
   546→  options: CompletionOptions = {}
   547→): Promise<string> {
   548→  const res = await fetch(AI_ENDPOINT, {
   549→    method: "POST",
   550→    headers: { "Content-Type": "application/json", Accept: "application/json" },
   551→    body: JSON.stringify({ model: AI_MODEL, messages, ...options }),
   552→  });
   553→  if (!res.ok) {
   554→    const body = await res.text();
   555→    throw new Error(`AI API ${res.status}: ${body}`);
   556→  }
   557→  const data = await res.json();
   558→  return data.choices[0].message.content;
   559→}
   560→
   561→export async function safeJsonCompletion<T = unknown>(
   562→  messages: ChatMessage[],
   563→  options: CompletionOptions = {}
   564→): Promise<T> {
   565→  const raw = await chatCompletion(messages, options);
   566→  const match = raw.match(/\{[\s\S]*\}|\[[\s\S]*\]/);
   567→  if (!match) throw new Error(`Expected JSON but got: ${raw.slice(0, 200)}`);
   568→  return JSON.parse(match[0]);
   569→}
   570→
   571→export async function withRetry<T>(fn: () => Promise<T>, maxAttempts = 3): Promise<T> {
   572→  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
   573→    try {
   574→      return await fn();
   575→    } catch (err) {
   576→      if (attempt === maxAttempts) throw err;
   577→      await new Promise((r) => setTimeout(r, 1000 * attempt));
   578→    }
   579→  }
   580→  throw new Error("unreachable");
   581→}
   582→
   583→// --- File encoding helpers ---
   584→
   585→export function fileToDataUri(file: File): Promise<string> {
   586→  return new Promise((resolve, reject) => {
   587→    const reader = new FileReader();
   588→    reader.onload = () => resolve(reader.result as string);
   589→    reader.onerror = () => reject(new Error("Failed to read file"));
   590→    reader.readAsDataURL(file);
   591→  });
   592→}
   593→
   594→export async function urlToDataUri(url: string): Promise<string> {
   595→  const res = await fetch(url);
   596→  const blob = await res.blob();
   597→  return new Promise((resolve, reject) => {
   598→    const reader = new FileReader();
   599→    reader.onload = () => resolve(reader.result as string);
   600→    reader.onerror = () => reject(new Error("Failed to encode file"));
   601→    reader.readAsDataURL(blob);
   602→  });
   603→}
   604→
   605→/** Convert a data URI back to a Blob (for file uploads) */
   606→export function dataUriToBlob(dataUri: string): Blob {
   607→  const [header, base64] = dataUri.split(',');
   608→  const mime = header.match(/:(.*?);/)?.[1] ?? 'application/octet-stream';
   609→  const bytes = atob(base64);
   610→  const arr = new Uint8Array(bytes.length);
   611→  for (let i = 0; i < bytes.length; i++) arr[i] = bytes.charCodeAt(i);
   612→  return new Blob([arr], { type: mime });
   613→}
